for name, k in KERNELS.items():
    src = (HERE / k['main']).read_text()
    for line in [l for l in src.splitlines() if '# @embed ' in l]:
        var, rel = line.split(' = ')[0], line.split('# @embed ')[1].strip()
        src = src.replace(line, f'{var} = {(HERE / rel).read_text()!r}')
    for line in [l for l in src.splitlines() if '# @embed_dir ' in l]:  # {bundle name: {relpath: text}}
        var, rels = line.split(' = ')[0], line.split('# @embed_dir ')[1].split()
        bundles = {Path(r).name: {str(p.relative_to(HERE / r)): p.read_text()
                                  for p in sorted((HERE / r).rglob('*'))
                                  if p.is_file() and '__pycache__' not in p.parts and p.suffix != '.pyc'} for r in rels}
        src = src.replace(line, f'{var} = {bundles!r}')
    for var, val in k.get('defines', {}).items():
        lines = src.splitlines(keepends=True)
        j = next(i for i, l in enumerate(lines) if l.startswith(f'{var} = ') and '# @define' in l)
        lines[j] = f'{var} = {val!r}\n'  # whole-line replace: 'DPO = {}  # @define' is also a substring of PHASE2_DPO's line
        src = ''.join(lines)
    out = ROOT / name
    out.mkdir(exist_ok=True)
    (out / f'{name}.py').write_text(src)
    (out / 'kernel-metadata.json').write_text(json.dumps({
        'id': f'verracodeguacas/{k["title"]}', 'title': k['title'], 'code_file': f'{name}.py',
        'language': 'python', 'kernel_type': 'script', 'is_private': True,
        'enable_gpu': k['enable_gpu'], 'enable_tpu': k['enable_tpu'], 'enable_internet': k['internet'],
        'machine_shape': k['machine_shape'], 'dataset_sources': k['datasets'],
        'competition_sources': ['gemma-4-developer-agent'], 'kernel_sources': k.get('kernels', []), 'model_sources': k['models'],
        **({'docker_image': k['docker_image']} if k.get('docker_image') else {}),
    }, indent=2))
    print('built', out / f'{name}.py', len(src), 'chars')

